import { motion } from "framer-motion";
import { galleryImages } from "../data/gallery";

export default function HorizontalGallery() {
  return (
    <div className="absolute top-24 left-1/2 -translate-x-1/2 w-[1800px] overflow-hidden z-0">
      <motion.div
        className="flex gap-5"
        animate={{
          x: [0, -700],
        }}
        transition={{
          repeat: Infinity,
          duration: 30,
          ease: "linear",
        }}
      >
        {[...galleryImages, ...galleryImages].map((item, index) => (
          <motion.div
            // key={index}
            style={{
              rotate: item.rotate,
              y: item.y,
            }}
            whileHover={{
              scale: 1.08,
            }}
            className="w-[300px] h-[210px] rounded-3xl overflow-hidden shrink-0 shadow-2xl"
          >
            <img
              src={item.image}
              className="w-full h-full object-cover"
              alt=""
            />
          </motion.div>
        ))}
      </motion.div>
    </div>
  );
}
